import sqlite3
con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
print("user_version:", con.execute("PRAGMA user_version").fetchone()[0])
tables = [t for (t,) in con.execute("select name from sqlite_master where type='table' order by name")]
counts = {t: con.execute(f'select count(*) from "{t}"').fetchone()[0] for t in tables}
print("TABLES:", len(tables))
print("--- non-empty, descending ---")
for t, n in sorted(((t,n) for t,n in counts.items() if n>0), key=lambda x:(-x[1],x[0])):
    print(f"{n}\t{t}")
print("--- EMPTY ---")
empty = {t for t,n in counts.items() if n==0}
for t in sorted(empty): print(t)
print("EMPTY COUNT:", len(empty))
print("--- UNWRITABLE ---")
found = 0
for t in tables:
    dead = {f[3] for f in con.execute(f'PRAGMA foreign_key_list("{t}")') if f[2] in empty}
    for c in con.execute(f'PRAGMA table_info("{t}")'):
        if c[1] in dead and c[3]:
            print(f"UNWRITABLE  {t}.{c[1]} -> empty table"); found += 1
print("UNWRITABLE COUNT:", found)
print("--- key tables ---")
for t in tables:
    if any(k in t for k in ('parameter','specification','source','extract','judg','evidence','determin','synth')):
        print(t, counts[t])
