import sqlite3
con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
tables = [t for (t,) in con.execute("select name from sqlite_master where type='table' order by name")]
# distinct session-like values across all tables with a session column, and per-session row attribution
for t in tables:
    cols = [c[1] for c in con.execute(f'PRAGMA table_info("{t}")')]
    for c in cols:
        if 'session' in c.lower():
            rows = con.execute(f'select "{c}", count(*) from "{t}" group by "{c}" order by 2 desc').fetchall()
            print(t, c, "distinct:", len(rows))
            for v,n in rows: print("  ", v, n)
